import Chart from "chart.js/auto";
import React, { useEffect, useRef, useState, useCallback } from "react";
const DATA_PATH = "/smogon_csv/";

export default function ComUsage() {
  const chartRef = useRef(null);
  const canvasRef = useRef(null);

  const [files, setFiles] = useState([]);
  const [selectedGen, setSelectedGen] = useState("9");
  const [selectedMonths, setSelectedMonths] = useState([]);
  const [menuOpen, setMenuOpen] = useState(false);

  // 🔍 Simulate file list (you can hardcode or improve later)
  useEffect(() => {
    const sampleFiles = [
      "2024-01_gen9doublesou-0.csv",
      "2024-02_gen9doublesou-0.csv",
      "2024-03_gen9doublesou-0.csv"
    ];
    setFiles(sampleFiles);
    setSelectedMonths(sampleFiles);
  }, []);

  const loadCSV = async (file) => {
    const res = await fetch(DATA_PATH + file);
    return await res.text();
  };

  const parseCSV = (text) => {
    return text.split("\n").slice(1).map(r => r.split(","));
  };

  const getTopPokemonUsage = useCallback(async () => {
    const labels = [];
    const data = [];

    for (let file of selectedMonths) {
      if (!file.includes(`gen${selectedGen}`)) continue;

      const text = await loadCSV(file);
      const rows = parseCSV(text);

      if (rows.length === 0) continue;

      const top = rows[0]; // top Pokémon
      const month = file.split("_")[0];

      labels.push(month);
      data.push(parseFloat(top[2]));
    }

    return { labels, data };
  }, [selectedGen, selectedMonths]);

  useEffect(() => {
    const buildChart = async () => {
      const { labels, data } = await getTopPokemonUsage();

      if (chartRef.current) chartRef.current.destroy();

      chartRef.current = new Chart(canvasRef.current, {
        type: "line",
        data: {
          labels,
          datasets: [
            {
              label: `Top Usage (Gen ${selectedGen})`,
              data,
              tension: 0.3
            }
          ]
        }
      });
    };

    buildChart();
  }, [selectedGen, selectedMonths]);

  return (
    <div>
      <h2>Competitive Usage Trends</h2>

      {/* 🍔 Burger Menu */}
      <div style={{ position: "absolute", top: 20, right: 20 }}>
        <button onClick={() => setMenuOpen(!menuOpen)}>☰</button>
      </div>

      {/* FILTER PANEL */}
      {menuOpen && (
        <div style={{
          position: "absolute",
          top: 60,
          right: 20,
          background: "#eee",
          padding: "15px",
          borderRadius: "8px"
        }}>
          <h4>Filters</h4>

          {/* Generation */}
          <label>Generation:</label>
          <select
            value={selectedGen}
            onChange={(e) => setSelectedGen(e.target.value)}
          >
            {[6,7,8,9].map(g => (
              <option key={g} value={g}>Gen {g}</option>
            ))}
          </select>

          <br /><br />

          {/* Months */}
          <label>Months:</label>
          {files.map(file => (
            <div key={file}>
              <input
                type="checkbox"
                checked={selectedMonths.includes(file)}
                onChange={() => {
                  setSelectedMonths(prev =>
                    prev.includes(file)
                      ? prev.filter(f => f !== file)
                      : [...prev, file]
                  );
                }}
              />
              {file.split("_")[0]}
            </div>
          ))}
        </div>
      )}

      <canvas ref={canvasRef}></canvas>
    </div>
  );
}
